import{_ as r,o as a,c as t,a3 as o}from"./chunks/framework.fntC-tS-.js";const u=JSON.parse('{"title":"Learning resources","description":"","frontmatter":{"title":"Learning resources"},"headers":[],"relativePath":"learning/index.md","filePath":"learning/index.md","lastUpdated":1794347414000}'),n={name:"learning/index.md"};function i(s,e,l,h,c,g){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="learning-resources" tabindex="-1">Learning resources <a class="header-anchor" href="#learning-resources" aria-label="Permalink to &quot;Learning resources&quot;">​</a></h1><p>Courses, tutorials and tools to get started with geocomputing. Some are free for the UNIL community, some are open to all.</p><h2 id="courses-and-tutorials" tabindex="-1">Courses and tutorials <a class="header-anchor" href="#courses-and-tutorials" aria-label="Permalink to &quot;Courses and tutorials&quot;">​</a></h2><ul><li><p><a href="https://wp.unil.ch/dawn/getting-started-with-machine-learning/" target="_blank" rel="noreferrer">Getting Started with Machine Learning</a>: a list of resources to help environmental scientists get started with machine learning. It includes tutorials with code, literature reviews, textbooks (often including code), and datasets that are already pre-processed for machine learning applications.</p></li><li><p><a href="https://github.com/GAIA-UNIL/Short-course-MPS" target="_blank" rel="noreferrer">Hands-on introduction to Multiple Point Statistics</a>: an introduction to stochastic simulation using multiple point statistics, a modelling approach based on the use of training images with the aim of generating realistic heterogeneity characterising natural processes.</p></li><li><p><a href="https://pde-on-gpu.vaw.ethz.ch/" target="_blank" rel="noreferrer">Solving PDEs in parallel on GPUs with Julia</a>: ETH&#39;s course 101-0250-00L on solving partial differential equations (PDEs) in parallel on graphical processing units (GPUs) with the Julia programming language.</p></li><li><p><a href="https://github.com/gse-unil" target="_blank" rel="noreferrer">FGSE geoinformatics and machine learning teaching materials</a>: course materials and notebooks on geoinformatics and machine learning for Earth and environmental sciences.</p></li><li><p><a href="https://www.coursera.org/epfl" target="_blank" rel="noreferrer">EPFL on Coursera</a>: a free platform where EPFL professors and others share plenty of high-level classes across many fields.</p></li><li><p><a href="https://www.youtube.com/" target="_blank" rel="noreferrer">YouTube</a>: a less formal platform with a ton of very good resources; always check whether there are tutorials for your needs. A few examples: <a href="https://www.youtube.com/c/CKaiser" target="_blank" rel="noreferrer">Christian Kaiser</a> has a great channel for cartography (in French), the <a href="https://www.youtube.com/c/BroCodez/videos" target="_blank" rel="noreferrer">Bro Code</a> for Python tutorials, <a href="https://www.youtube.com/c/TheAIGuy/videos" target="_blank" rel="noreferrer">The AI Guy</a> for machine learning.</p></li></ul><h2 id="workshop-and-meet-up-material" tabindex="-1">Workshop and meet-up material <a class="header-anchor" href="#workshop-and-meet-up-material" aria-label="Permalink to &quot;Workshop and meet-up material&quot;">​</a></h2><ul><li><a href="/events/pkg-workshop">Packaging workshop (Python and Julia)</a>: from a Jupyter notebook to a package, with the <a href="https://github.com/Unil-SGC/python-packaging" target="_blank" rel="noreferrer">Python</a> and <a href="https://github.com/Unil-SGC/julia-packaging" target="_blank" rel="noreferrer">Julia</a> material.</li><li><a href="https://github.com/Unil-SGC/geocomputing-coffee" target="_blank" rel="noreferrer">Geocomputing coffee</a>: Git, GitHub and remote development basics from the <a href="/events/geocomp-coffee-1">first</a> and <a href="/events/geocomp-coffee-2">second</a> meet-ups.</li><li><a href="https://github.com/Unil-SGC/AGDA-Rbook" target="_blank" rel="noreferrer">Advanced geospatial data analysis</a>: the R book of the course.</li></ul><h2 id="open-source-programming-languages" tabindex="-1">Open-source programming languages <a class="header-anchor" href="#open-source-programming-languages" aria-label="Permalink to &quot;Open-source programming languages&quot;">​</a></h2><ul><li><a href="https://julialang.org/" target="_blank" rel="noreferrer">Julia</a>: designed from the beginning for high performance.</li><li><a href="https://www.python.org/" target="_blank" rel="noreferrer">Python</a>: a programming language that lets you work more quickly and integrate your systems more effectively.</li><li><a href="https://www.r-project.org/" target="_blank" rel="noreferrer">R</a>: a free software environment for statistical computing and graphics.</li><li><a href="https://octave.org/" target="_blank" rel="noreferrer">Octave</a>: a free alternative to <a href="https://www.mathworks.com/products/matlab.html" target="_blank" rel="noreferrer">MATLAB</a>, useful for students who used that language during their studies.</li></ul><p>For a more detailed comparison, read <a href="https://towardsdatascience.com/r-vs-python-vs-julia-90456a2bcbab" target="_blank" rel="noreferrer">R vs. Python vs. Julia</a>.</p><h2 id="web-services-for-developers" tabindex="-1">Web services for developers <a class="header-anchor" href="#web-services-for-developers" aria-label="Permalink to &quot;Web services for developers&quot;">​</a></h2><ul><li><p><a href="https://git-scm.com/" target="_blank" rel="noreferrer">Git</a>: software that helps developers and data scientists store and manage their code and other text-based resources, track and control changes, and collaborate with others. Several web services host Git repositories and make them accessible: <a href="https://github.com/" target="_blank" rel="noreferrer">GitHub</a> is the best known, others are <a href="https://gitlab.com/explore" target="_blank" rel="noreferrer">GitLab</a>, <a href="https://bitbucket.org/" target="_blank" rel="noreferrer">Bitbucket</a> and <a href="https://codeberg.org/" target="_blank" rel="noreferrer">Codeberg</a>.</p></li><li><p><a href="https://jupyter.org/" target="_blank" rel="noreferrer">Jupyter</a>: free software, open standards and web services for interactive computing across all programming languages.</p></li><li><p><a href="https://colab.research.google.com/" target="_blank" rel="noreferrer">Google Colaboratory</a>: a hosted Jupyter notebook service that requires no setup, with free access to computing resources including GPUs.</p></li></ul>',11)])])}const f=r(n,[["render",i]]);export{u as __pageData,f as default};
